std::decay_t<decltype(left)> result;
for (const auto& item : left) {
    bool inRight = std::find(right.begin(), right.end(), item) != right.end();
    if (inRight == false && std::find(result.begin(), result.end(), item) == result.end()) result.push_back(item);
}
return result;

